const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point([141.780304, -27.667421]);
  const region = point.buffer(10000); // 10km radius
  const date1 = '2025-04-06';
  const date2 = '2025-04-22';

  // 2. Data Acquisition - Sentinel-2 for NDVI
  function getImage(date) {
    const start = ee.Date(date);
    const end = start.advance(1, 'day');

    return ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterBounds(region)
      .filterDate(start, end)
      .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30))
      .map(function(image) {
        // Calculate NDVI
        const ndvi = image.normalizedDifference(['B8', 'B4']).rename('NDVI');
        // Cloud masking using QA60 band
        const qa = image.select('QA60');
        const cloudBitMask = 1 << 10;
        const cirrusBitMask = 1 << 11;
        const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
                     .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
        return ndvi.updateMask(mask).copyProperties(image, ['system:time_start']);
      })
      .median(); // Use median composite
  }

  const img1 = getImage(date1);
  const img2 = getImage(date2);

  // Check collection sizes
  const col1 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(region)
    .filterDate('2025-04-06', '2025-04-07');
  const col2 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(region)
    .filterDate('2025-04-22', '2025-04-23');

  const count1 = col1.size().getInfo();
  const count2 = col2.size().getInfo();

  console.log(`${date1} Images: ${count1}`);
  console.log(`${date2} Images: ${count2}`);

  if (count1 === 0 || count2 === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Check valid pixels
  const stats1 = img1.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const stats2 = img2.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const validPixels1 = stats1.NDVI || 0;
  const validPixels2 = stats2.NDVI || 0;

  console.log(`Valid pixels ${date1}: ${validPixels1}`);
  console.log(`Valid pixels ${date2}: ${validPixels2}`);

  if (validPixels1 === 0 || validPixels2 === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // 4. Calculation - Compare NDVI means
  const ndvi1 = img1.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: 3000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  const ndvi2 = img2.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: 3000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  // 5. Validation & Final Answer
  console.log(`NDVI ${date1}: ${ndvi1 !== null ? ndvi1.toFixed(3) : 'null'}`);
  console.log(`NDVI ${date2}: ${ndvi2 !== null ? ndvi2.toFixed(3) : 'null'}`);

  if (ndvi1 === null || ndvi2 === null || 
      Math.abs(ndvi1) > 1 || Math.abs(ndvi2) > 1 || 
      isNaN(ndvi1) || isNaN(ndvi2)) {
    console.log("<answer>C3</answer>");
  } else if (ndvi2 > ndvi1) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
